    40	static void
    41	_fill_map (uint32_t c, const uint8_t * p, IDNAMap * map)
    42	{
    43	  uint32_t value;
    44	
    45	  if (c <= 0xFF)
    46	    {
    47	      map->cp1 = *p++;
    48	      map->range = *p++;
    49	    }
    50	  else if (c <= 0xFFFF)
    51	    {
    52	      map->cp1 = (p[0] << 8) | p[1];
    53	      map->range = (p[2] << 8) | p[3];
    54	      p += 4;
    55	    }
    56	  else
    57	    {
    58	      map->cp1 = (p[0] << 16) | (p[1] << 8) | p[2];
    59	      map->range = (p[3] << 8) | p[4];
    60	      p += 5;
    61	    }
    62	
    63	  value = (p[0] << 16) | (p[1] << 8) | p[2];
    64	
    65	  /* deconstruct value, construction was
    66	   *   value = (((map->nmappings << 14) | map->offset) << 3) | map->flag_index; */
    67	  map->flag_index = value & 0x7;
    68	  map->offset = (value >> 3) & 0x3FFF;
    69	  map->nmappings = (value >> 17) & 0x1F;
    70	}
